/* Personnel, rôles & permissions, établissements, sécurité, audit, sauvegardes */
(function () {
  const N = Nacre, D = N.D, A = N.App, H = A.H;
  const { icon, fmt, esc, avatar, badge, toast, modal, formData } = N.ui;

  /* =================== PERSONNEL =================== */
  const PT = { tab: 'equipe' };
  A.view('personnel', {
    render() {
      const S = N.S; const staff = S.staff.filter(s => N.inClinic(s));
      const tabs = `<div class="tabs mb-16">${[['equipe', 'Équipe'], ['roles', 'Rôles & permissions'], ['praticiens', 'Praticiens']].map(([k, l]) => `<button class="${PT.tab === k ? 'on' : ''}" data-pt="${k}">${l}</button>`).join('')}</div>`;
      let body = '';
      if (PT.tab === 'equipe') body = `<div class="grid g4 mb-16">${Object.entries(S.roles).slice(0, 4).map(([k, v], i) => H.kpi(v + (k === 'admin' ? 's' : 's'), staff.filter(s => s.role === k || (k === 'admin' && s.admin)).length, ['shield', 'tooth', 'user', 'phone'][i], ['tone-gold', 'tone-blue', 'tone-teal', 'tone-sage'][i])).join('')}</div>
        <div class="card"><div class="table-wrap"><table class="table responsive"><thead><tr><th>Membre</th><th>Rôle</th><th>Établissement</th><th>Contact</th><th>2FA</th><th>Dernière connexion</th></tr></thead><tbody>${staff.map((s, i) => `<tr><td data-l="Membre"><div class="row">${avatar(s, 'sm')}<div><b style="font-weight:500">${esc(N.name(s))}</b>${s.spec ? `<div class="xs muted">${esc(s.spec)}</div>` : ''}</div></div></td><td data-l="Rôle">${badge(S.roles[s.role], s.role === 'admin' ? 'tone-gold' : s.role === 'dentiste' ? 'st-confirme' : 'tone-gray', false)}${s.admin ? ' ' + badge('Admin', 'tone-gold', false) : ''}</td><td data-l="Site">${s.clinic === 'all' ? 'Tous les sites' : esc(N.clinic(s.clinic).city)}</td><td data-l="Contact" class="small">${s.email}<div class="xs muted">${s.phone}</div></td><td data-l="2FA">${s.twofa ? badge('Activée', 'st-termine') : badge('Non activée', 'st-noshow')}</td><td data-l="Connexion" class="small muted">${i < 4 ? 'aujourd’hui ' + ['08:02', '08:05', '07:58', '08:40'][i] : 'il y a ' + (i % 4 + 1) + ' j'}</td></tr>`).join('')}</tbody></table></div></div>`;
      else if (PT.tab === 'roles') body = `<div class="card mb-16" style="background:var(--primary-50);border-color:var(--primary-100)"><div class="card-body row small">${icon('info').replace('<svg', '<svg style="width:18px;height:18px;color:var(--primary);flex:none"')}<span>Permissions granulaires par rôle. Exemple : la <b>secrétaire</b> gère les rendez-vous et les paiements mais ne peut pas consulter ni modifier les informations cliniques sensibles. Utilisez le menu utilisateur (en haut à droite) pour simuler un rôle.</span></div></div>
        <div class="card"><div class="table-wrap"><table class="table perm-table"><thead><tr><th>Permission</th>${Object.values(S.roles).map(r => `<th>${r}</th>`).join('')}</tr></thead><tbody>${S.perms.map(([k, l]) => `<tr><td>${l}<div class="xs faint mono">${k}</div></td>${Object.keys(S.roles).map(r => { const on = S.rolePerms[r].includes(k); return `<td><span class="perm-cell ${on ? 'on' : ''}" data-perm="${r}|${k}" ${r === 'admin' ? 'style="opacity:.6;cursor:not-allowed" title="L’administrateur dispose de toutes les permissions"' : ''}>${on ? icon('check') : ''}</span></td>`; }).join('')}</tr>`).join('')}</tbody></table></div></div>`;
      else body = `<div class="grid g3">${S.staff.filter(s => s.role === 'dentiste' && N.inClinic(s)).map(d => { const t = D.todayYmd(); const x = S.appts.filter(a => a.dentist === d.id && a.date.slice(0, 7) === t.slice(0, 7)); const pts = S.patients.filter(p => p.dentist === d.id).length; const rv = S.reviews.filter(r => r.dentist === d.id); return `<div class="card"><div class="card-body"><div class="row">${avatar(d, 'lg')}<div><b style="font-size:15px">${esc(N.name(d))}</b><div class="small muted">${esc(d.spec)}</div><div class="xs muted">${esc(N.clinic(d.clinic).name)} · ${esc(d.chair)}</div></div></div><div class="grid g2 mt-16" style="gap:8px">${[['RDV ce mois', x.length], ['Aujourd’hui', x.filter(a => a.date === t).length], ['Patients suivis', pts], ['Satisfaction', '★ ' + (rv.reduce((s, r) => s + r.rating, 0) / (rv.length || 1)).toFixed(1).replace('.', ',')]].map(([l, v]) => `<div style="padding:9px 12px;border:1px solid var(--line);border-radius:10px"><div class="xs muted">${l}</div><b>${v}</b></div>`).join('')}</div><div class="row mt-12"><button class="btn sm grow" data-agenda="${d.id}">${icon('calendar')}Agenda</button></div></div></div>`; }).join('')}</div>`;
      return H.head('Personnel', 'Équipe, rôles et permissions granulaires', `<button class="btn primary" data-ns>${icon('plus')}Ajouter un membre</button>`) + tabs + body;
    },
    mount(el) {
      const S = N.S;
      el.querySelectorAll('[data-pt]').forEach(b => b.onclick = () => { PT.tab = b.dataset.pt; A.refresh(); });
      el.querySelectorAll('[data-perm]').forEach(c => c.onclick = () => { const [r, k] = c.dataset.perm.split('|'); if (r === 'admin') return; const arr = S.rolePerms[r]; const i = arr.indexOf(k); if (i >= 0) arr.splice(i, 1); else arr.push(k); N.log('Permission ' + (i >= 0 ? 'retirée' : 'accordée'), S.roles[r] + ' — ' + k); N.save(); A.refresh(); toast(`${S.roles[r]} : ${i >= 0 ? 'retrait' : 'ajout'} de « ${S.perms.find(p => p[0] === k)[1]} »`, 'shield'); });
      el.querySelectorAll('[data-agenda]').forEach(b => b.onclick = () => { N.Agenda.st.view = 'dentiste'; N.Agenda.st.dentist = b.dataset.agenda; location.hash = '#/agenda'; });
      el.querySelector('[data-ns]').onclick = () => modal({ title: 'Ajouter un membre', body: `<form class="form-grid" id="fst"><div class="field"><label>Prénom</label><input class="input" name="first"></div><div class="field"><label>Nom</label><input class="input" name="last"></div><div class="field"><label>Rôle</label><select class="select" name="role">${Object.entries(S.roles).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select></div><div class="field"><label>Établissement</label><select class="select" name="clinic">${S.clinics.map(c => `<option value="${c.id}">${c.name}</option>`).join('')}<option value="all">Tous les sites</option></select></div><div class="field full"><label>Email professionnel</label><input class="input" type="email" name="email"></div><label class="check full"><input type="checkbox" name="twofa" checked> Imposer la double authentification (2FA)</label><p class="xs muted full">Une invitation sécurisée (lien à usage unique, 48h) sera envoyée. Le membre définit lui-même son mot de passe.</p></form>`, foot: `<button class="btn" data-close>Annuler</button><button class="btn primary" data-s>Envoyer l’invitation</button>`,
        onMount: m => m.querySelector('[data-s]').onclick = () => { const d = formData(m.querySelector('#fst')); if (!d.first || !d.last) return toast('Nom requis', 'alert'); S.staff.push({ id: N.uid('s'), first: d.first, last: d.last, title: d.role === 'dentiste' ? 'Dr.' : '', role: d.role, clinic: d.clinic, color: '#4B7BB5', email: d.email, phone: '', twofa: d.twofa, spec: d.role === 'dentiste' ? 'Omnipratique' : '', chair: 'Fauteuil 1' }); N.log('Invitation membre', d.first + ' ' + d.last + ' (' + S.roles[d.role] + ')'); N.save(); m.close(); A.refresh(); toast('Invitation envoyée à ' + esc(d.email || d.first), 'send'); } });
    }
  });

  /* =================== PARAMÈTRES =================== */
  const ST = { tab: 'cabinet', q: '' };
  A.view('parametres', {
    render() {
      const S = N.S; const sec = S.settings.security;
      const tabs = `<div class="tabs mb-16">${[['cabinet', 'Cabinet', 'building'], ['sites', 'Établissements', 'layers'], ['securite', 'Sécurité', 'shield'], ['audit', 'Journal d’audit', 'history'], ['sauvegardes', 'Sauvegardes', 'database'], ['reservation', 'Réservation en ligne', 'globe']].map(([k, l, ic]) => `<button class="${ST.tab === k ? 'on' : ''}" data-st="${k}">${icon(ic).replace('<svg', '<svg style="width:15px;height:15px"')}${l}</button>`).join('')}</div>`;
      let body = '';
      if (ST.tab === 'cabinet') body = `<div class="grid g2"><div class="card"><div class="card-head"><h3>Identité du groupe</h3></div><div class="card-body"><form class="form-grid" id="fset"><div class="field full"><label>Nom commercial</label><input class="input" name="group" value="${esc(S.settings.group)}"></div><div class="field full"><label>Raison sociale</label><input class="input" name="legal" value="${esc(S.settings.legal)}"></div><div class="field"><label>ICE</label><input class="input" name="ice" value="${S.settings.ice}"></div><div class="field"><label>RC</label><input class="input" name="rc" value="${S.settings.rc}"></div><div class="field"><label>INPE</label><input class="input" name="inpe" value="${S.settings.inpe}"></div><div class="field"><label>Devise</label><input class="input" value="Dirham (DH)" disabled></div></form><button class="btn primary mt-16" data-saveset>${icon('check')}Enregistrer</button></div></div>
        <div class="col gap-16"><div class="card"><div class="card-head"><h3>Horaires d’ouverture</h3></div><div class="card-body"><dl class="kv"><dt>Lundi – vendredi</dt><dd>${S.settings.hours.open} – ${S.settings.hours.close}</dd><dt>Pause déjeuner</dt><dd>${S.settings.hours.lunch.join(' – ')}</dd><dt>Samedi</dt><dd>${S.settings.hours.open} – ${S.settings.hours.saturday}</dd><dt>Dimanche</dt><dd>Fermé</dd></dl></div></div>
        <div class="card"><div class="card-head"><h3>Catalogue des actes</h3><span class="xs muted">${S.acts.length} actes</span></div><div class="card-body" style="max-height:300px;overflow:auto"><div class="list">${S.acts.map(a => `<div class="li"><span class="tag mono">${a.code}</span><div class="grow small">${esc(a.label)}</div><b class="mono small">${fmt.money(a.price)}</b></div>`).join('')}</div></div></div></div></div>`;
      else if (ST.tab === 'sites') body = `<div class="grid g3 mb-16">${S.clinics.map(c => { const h = S.history[c.id][11]; return `<div class="card"><div class="card-body"><div class="row"><span class="clinic-dot" style="width:40px;height:40px">${icon('building')}</span><div><b style="font-size:15px">${c.name}</b><div class="xs muted">${esc(c.address)}</div></div></div><div class="grid g2 mt-16" style="gap:8px">${[['Praticiens', S.staff.filter(s => s.clinic === c.id && s.role === 'dentiste').length], ['Fauteuils', c.chairs.length], ['Patients', S.patients.filter(p => p.clinic === c.id).length], ['CA du mois', fmt.k(h.revenue) + ' DH']].map(([l, v]) => `<div style="padding:9px 12px;border:1px solid var(--line);border-radius:10px"><div class="xs muted">${l}</div><b>${v}</b></div>`).join('')}</div><button class="btn sm mt-12" style="width:100%" data-goclinic="${c.id}">${icon('arrowRight')}Ouvrir ce cabinet</button></div></div>`; }).join('')}</div>
        <div class="card"><div class="card-head"><h3>Architecture multi-tenant</h3></div><div class="card-body"><div class="grid g3" style="gap:12px">${[['Isolation des données', 'Chaque établissement dispose de son propre espace logique (patients, agenda, stock, finances). Les requêtes sont filtrées par identifiant de tenant au niveau base de données (Row-Level Security).', 'lock'], ['Vue direction', 'Le rôle Administrateur accède à un tableau de bord consolidé sans dupliquer les données — agrégations en lecture seule.', 'layers'], ['Partage contrôlé', 'Un patient peut être suivi dans plusieurs sites uniquement après transfert de dossier tracé dans le journal d’audit.', 'repeat']].map(([t, d, ic]) => `<div style="padding:14px;border:1px solid var(--line);border-radius:12px"><span class="avatar sm" style="background:var(--primary-50);color:var(--primary)">${icon(ic).replace('<svg', '<svg style="width:14px"')}</span><b class="mt-8" style="display:block">${t}</b><p class="small muted mt-4">${d}</p></div>`).join('')}</div><button class="btn mt-16">${icon('plus')}Ajouter un établissement</button></div></div>`;
      else if (ST.tab === 'securite') body = `<div class="grid g2"><div class="card"><div class="card-head"><h3>Authentification & sessions</h3></div><div class="card-body col" style="gap:14px">
          ${[['twofa', 'Double authentification (2FA) obligatoire', 'Application TOTP ou SMS pour tous les membres', sec.twofa], ['ipAllow', 'Restreindre l’accès aux IP du cabinet', 'Accès hors cabinet uniquement via l’application mobile', sec.ipAllow]].map(([k, l, d, on]) => `<div class="row between"><div><b style="font-weight:500">${l}</b><div class="xs muted">${d}</div></div><label class="switch"><input type="checkbox" data-sec="${k}" ${on ? 'checked' : ''}><span></span></label></div>`).join('')}
          <div class="row between"><div><b style="font-weight:500">Expiration de session</b><div class="xs muted">Déconnexion après inactivité</div></div><select class="select sm" id="sto" style="width:120px">${[15, 30, 60, 120].map(v => `<option ${sec.sessionTimeout === v ? 'selected' : ''} value="${v}">${v} min</option>`).join('')}</select></div>
          <div class="row between"><div><b style="font-weight:500">Politique de mot de passe</b><div class="xs muted">12 caractères min., vérification des fuites, rotation 180 j</div></div>${badge('Forte', 'st-termine')}</div>
          <div class="divider" style="margin:0"></div><div class="xs muted">Sessions actives</div>
          ${[['Dr. Salma Bennani', 'Chrome · Windows · Fès', 'Session actuelle'], ['Dr. Salma Bennani', 'App iOS · iPhone 15', 'il y a 2 h'], ['Mounia Rahmani', 'Edge · Accueil Fès', 'il y a 5 min'], ['Adil Benomar', 'Firefox · Rabat', 'hier']].map(([u, d, w], i) => `<div class="row"><span class="avatar xs" style="background:var(--navy)">${u.split(' ').slice(-1)[0][0]}</span><div class="grow small"><b style="font-weight:500">${u}</b> · ${d}<div class="xs muted">${w}</div></div>${i ? `<button class="btn xs danger" data-revoke>Révoquer</button>` : badge('Vous', 'tone-blue', false)}</div>`).join('')}
        </div></div>
        <div class="col gap-16"><div class="card"><div class="card-head"><h3>Protection des données</h3></div><div class="card-body col" style="gap:10px">${[['Chiffrement', sec.encryption, 'lock'], ['Contrôle d’accès', 'RBAC + permissions granulaires + accès dossier tracé', 'key'], ['Historique', 'Versionnage de chaque modification clinique (qui, quoi, quand)', 'history'], ['Isolation', 'Cloisonnement des données par établissement (multi-tenant)', 'layers'], ['Sauvegardes', sec.backups, 'database'], ['Hébergement', 'Hébergement de données de santé dans la région de déploiement', 'globe']].map(([t, d, ic]) => `<div class="row top"><span class="avatar sm" style="background:var(--success-50);color:var(--success)">${icon(ic).replace('<svg', '<svg style="width:14px"')}</span><div><b style="font-weight:500">${t}</b><div class="small muted">${d}</div></div></div>`).join('')}</div></div>
          <div class="card premium"><div class="card-body small"><b class="row gap-6">${icon('shield').replace('<svg', '<svg style="width:16px;height:16px;color:var(--gold)"')}Conformité</b><p class="muted mt-8">La plateforme est conçue pour permettre la conformité aux exigences applicables dans le pays de déploiement (par ex. loi 09-08 et CNDP au Maroc, RGPD en Europe) : registre des traitements, consentements tracés, droits d’accès et de rectification, export du dossier patient, durée de conservation paramétrable.</p></div></div></div></div>`;
      else if (ST.tab === 'audit') { const list = S.audit.filter(a => !ST.q || (a.user + a.action + a.target).toLowerCase().includes(ST.q.toLowerCase())); body = `<div class="card"><div class="card-body row between wrap"><div class="search" style="max-width:320px">${icon('search')}<input id="aq" placeholder="Utilisateur, action, patient…" value="${esc(ST.q)}" style="padding-right:12px"></div><span class="small muted">${list.length} événements · journal inaltérable (append-only)</span></div><div class="table-wrap"><table class="table responsive"><thead><tr><th>Date</th><th>Utilisateur</th><th>Action</th><th>Cible</th><th>IP</th></tr></thead><tbody>${list.slice(0, 150).map(a => `<tr><td data-l="Date" class="nowrap small">${fmt.date(a.at)} ${fmt.time(a.at)}</td><td data-l="Utilisateur"><b style="font-weight:500">${esc(a.user)}</b></td><td data-l="Action">${esc(a.action)}</td><td data-l="Cible" class="small muted">${esc(a.target)}</td><td data-l="IP" class="xs mono muted">${a.ip}</td></tr>`).join('')}</tbody></table></div></div>`; }
      else if (ST.tab === 'sauvegardes') body = `<div class="grid g2"><div class="card"><div class="card-head"><h3>Sauvegardes automatiques</h3>${badge('Actives', 'st-termine')}</div><div class="card-body"><p class="small muted">${sec.backups}. Chiffrement AES-256, clés gérées séparément.</p><div class="list mt-12">${Array.from({ length: 6 }, (_, i) => `<div class="li"><span class="avatar sm" style="background:var(--success-50);color:var(--success)">${icon('database').replace('<svg', '<svg style="width:14px"')}</span><div class="grow"><div class="t small">Snapshot ${fmt.date(D.addYmd(D.todayYmd(), -i - 1))} · 03:00</div><div class="s">3 sites · ${(412 - i * 1.3).toFixed(1).replace('.', ',')} Mo · vérifié</div></div><button class="btn xs" data-restore>Restaurer</button></div>`).join('')}</div><button class="btn primary mt-12" data-backup>${icon('refresh')}Lancer une sauvegarde maintenant</button></div></div>
        <div class="card"><div class="card-head"><h3>Export & portabilité</h3></div><div class="card-body col" style="gap:12px"><p class="small muted">Exportez l’intégralité des données du cabinet au format ouvert (JSON) — utile pour la portabilité, l’archivage ou une migration.</p><button class="btn" data-export>${icon('download')}Exporter toutes les données (JSON)</button><div class="divider" style="margin:0"></div><p class="small muted">Données de démonstration stockées localement dans ce navigateur.</p><button class="btn danger" data-reset>${icon('refresh')}Réinitialiser la démo</button></div></div></div>`;
      else body = `<div class="grid g2"><div class="card"><div class="card-head"><h3>Page publique « Prendre rendez-vous »</h3><label class="switch"><input type="checkbox" data-bk ${S.settings.booking.enabled ? 'checked' : ''}><span></span></label></div><div class="card-body col" style="gap:14px"><div class="field"><label>Lien public</label><div class="row"><input class="input" value="nacre.ma/rdv/centre-dentaire-atlas" readonly><a class="btn" href="reserver.html" target="_blank">${icon('eye')}Ouvrir</a></div></div><div class="field"><label>Types réservables en ligne</label><div class="chips">${Object.entries(S.types).map(([k, t]) => `<button class="chip ${S.settings.booking.types.includes(k) ? 'on' : ''}" data-bt="${k}">${t.label}</button>`).join('')}</div></div><div class="row"><div class="field grow"><label>Délai minimum (heures)</label><input class="input" type="number" data-bn="minNotice" value="${S.settings.booking.minNotice}"></div><div class="field grow"><label>Réservation jusqu’à (jours)</label><input class="input" type="number" data-bn="maxDays" value="${S.settings.booking.maxDays}"></div></div><p class="xs muted">Seuls les créneaux réellement disponibles dans l’agenda sont proposés. Confirmation automatique par SMS/email.</p></div></div>
        <div class="card"><div class="card-head"><h3>Widget pour votre site web</h3></div><div class="card-body"><pre style="background:var(--navy);color:#DCE6F5;padding:14px;border-radius:10px;font-size:12px;overflow:auto;margin:0">&lt;script src="https://cdn.nacre.ma/widget.js"
  data-cabinet="centre-dentaire-atlas"
  data-couleur="#2C6BCB"&gt;&lt;/script&gt;</pre><p class="small muted mt-12">Ajoutez un bouton « Prendre rendez-vous » sur votre site, Google Business Profile ou Instagram.</p></div></div></div>`;
      return H.head('Paramètres', 'Cabinet, établissements, sécurité et conformité') + tabs + body;
    },
    mount(el) {
      const S = N.S; const sec = S.settings.security;
      el.querySelectorAll('[data-st]').forEach(b => b.onclick = () => { ST.tab = b.dataset.st; A.refresh(); });
      const ss = el.querySelector('[data-saveset]'); if (ss) ss.onclick = () => { Object.assign(S.settings, formData(el.querySelector('#fset'))); N.log('Paramètres du cabinet modifiés', ''); N.save(); A.render(); toast('Paramètres enregistrés'); };
      el.querySelectorAll('[data-goclinic]').forEach(b => b.onclick = () => { S.session.clinic = b.dataset.goclinic; N.save(); location.hash = '#/dashboard'; location.reload(); });
      el.querySelectorAll('[data-sec]').forEach(i => i.onchange = () => { sec[i.dataset.sec] = i.checked; N.log('Sécurité : ' + i.dataset.sec + ' → ' + (i.checked ? 'activé' : 'désactivé'), ''); N.save(); toast('Paramètre de sécurité mis à jour', 'shield'); });
      const sto = el.querySelector('#sto'); if (sto) sto.onchange = () => { sec.sessionTimeout = +sto.value; N.save(); toast('Expiration de session : ' + sto.value + ' min', 'clock'); };
      el.querySelectorAll('[data-revoke]').forEach(b => b.onclick = () => { b.closest('.row').style.opacity = .4; b.remove(); N.log('Session révoquée', ''); N.save(); toast('Session révoquée', 'lock'); });
      const aq = el.querySelector('#aq'); if (aq) aq.onchange = e => { ST.q = e.target.value; A.refresh(); };
      const bk = el.querySelector('[data-backup]'); if (bk) bk.onclick = () => { bk.disabled = true; bk.innerHTML = 'Sauvegarde en cours…'; setTimeout(() => { N.log('Sauvegarde manuelle chiffrée', '3 sites'); N.save(); A.refresh(); toast('Sauvegarde chiffrée terminée', 'database'); }, 1200); };
      el.querySelectorAll('[data-restore]').forEach(b => b.onclick = () => toast('Restauration : validation par un second administrateur requise', 'shield'));
      const ex = el.querySelector('[data-export]'); if (ex) ex.onclick = () => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify(S, null, 2)], { type: 'application/json' })); a.download = 'nacre-export-' + D.todayYmd() + '.json'; a.click(); N.log('Export complet des données', 'JSON'); N.save(); };
      const rs = el.querySelector('[data-reset]'); if (rs) rs.onclick = async () => { if (await N.ui.confirmBox('Réinitialiser la démo ?', 'Toutes les modifications locales seront perdues.', 'Réinitialiser', true)) { N.reset(); location.reload(); } };
      const bkE = el.querySelector('[data-bk]'); if (bkE) bkE.onchange = () => { S.settings.booking.enabled = bkE.checked; N.save(); toast('Réservation en ligne ' + (bkE.checked ? 'activée' : 'désactivée'), 'globe'); };
      el.querySelectorAll('[data-bt]').forEach(b => b.onclick = () => { const arr = S.settings.booking.types; const i = arr.indexOf(b.dataset.bt); if (i >= 0) arr.splice(i, 1); else arr.push(b.dataset.bt); N.save(); A.refresh(); });
      el.querySelectorAll('[data-bn]').forEach(i => i.onchange = () => { S.settings.booking[i.dataset.bn] = +i.value; N.save(); });
    }
  });
})();
